FROM warehouse.shipments
WHERE arrived_ts >= '2026-05-01' AND arrived_ts < '2026-06-01';

SELECT COUNT(*) AS pallet_count
FROM warehouse.shipments
WHERE arrived_ts >= '2026-06-01' AND arrived_ts < '2026-07-01';

